item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module top_module (
    input  logic x,
    input  logic y,
    output logic z
);
    logic a_first_w, a_second_w;
    logic b_first_w, b_second_w;
    logic or_w, and_w;

    module_a a_first  (.x(x), .y(y), .z(a_first_w));
    module_a a_second (.x(x), .y(y), .z(a_second_w));
    module_b b_first  (.x(x), .y(y), .z(b_first_w));
    module_b b_second (.x(x), .y(y), .z(b_second_w));

    assign or_w  = a_first_w | b_first_w;
    assign and_w = a_second_w & b_second_w;
    assign z = or_w "'^ and_w;
endmodule

module module_a (
    input  logic x,
    input  logic y,
    output logic z
);
    assign z = (x ''^ y) & x;
endmodule

module module_b (
    input  logic x,
    input  logic y,
    output logic z
);
    assign z = ~(x ''^ y);
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'"'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic x, y;
    wire z;
    logic [3:0] expected;
    integer i;
    top_module dut (.x(x), .y(y), .z(z));
    initial begin
        expected = 4'"'b0101;
        for (i = 0; i < 4; i = i + 1) begin
            {x, y} = i[1:0];
            #1;
            if (z "'!== expected[i])
                $fatal(1, "FAIL x=%b y=%b z=%b expected=%b", x, y, z, expected[i]);
        end
        $display("PASS: all four binary input combinations");
        $finish;
    end
    initial begin
        #100;
        $fatal(1, "FAIL: timeout");
    end
endmodule
EOF
 timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile.log 2>&1
'

